-- Resources content for the purge fix (CLAUDE.md, "Resources stay in step with the code"). Content only; no schema.
-- Follows 20261111180000, which stops the purge deleting a conversation that holds a contact card a reviewer has acted on. The guide that
-- describes the purge says so. It is an update in place: a guide an editor has changed since is flagged for review and not overwritten.
--
-- Station-neutral on purpose: a guide is kept data, and the fresh-install check fails on any kept guide that names a station.

select private.rc_release_guide(
  p_slug => 'audience-listening-tonight-tables-and-purging',
  p_tool_key => 'audience-listening',
  p_title => 'Tonight, tables after the session and purging',
  p_summary => 'Run an event, send a recording to Sourcework, review what the facilitator marked and the contact cards, and purge what is due.',
  p_screen_keys => array['audience-listening.tonight', 'audience-listening.table', 'audience-listening.purge'],
  p_sort_order => 70,
  p_version_note => 'The purge keeps a conversation with an acted-on contact card',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Three screens cover the session itself and what follows it: "},{"type":"text","text":"Tonight","marks":[{"type":"bold"}]},{"type":"text","text":" while an event runs, the "},{"type":"text","text":"Table","marks":[{"type":"bold"}]},{"type":"text","text":" page after it, and "},{"type":"text","text":"Purge","marks":[{"type":"bold"}]},{"type":"text","text":" for retention."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Tonight"}]},{"type":"paragraph","content":[{"type":"text","text":"Open Tonight from an event. Keep it open for the session."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"It checks in every 15 seconds. Tables are told that help is coming only while a screen like this is open; otherwise their phone says the request is flagged and, if it is urgent, to ask at the front."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Turn sound on","marks":[{"type":"bold"}]},{"type":"text","text":" so a new request for a hand makes a tone as well as a notice. Browsers only allow sound after you click, so it starts off."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A table that asks for a hand shows a badge. Choose \"Someone is on the way\" once it is dealt with."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Move the room to a prompt, or call the last five minutes, which tables then see. A last call is made once."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The After list shows where each table's recording has got to. Nothing reminds anyone to finish, because the Portal has no background jobs: look at it the next day for tables still marked Recording or Uploading."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"After a table"}]},{"type":"paragraph","content":[{"type":"text","text":"Open a table from its event. It shows when the table agreed, to which wording version, and how much was recorded."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Once the table has ended and every segment has uploaded, choose Send to Sourcework. It needs access to Sourcework. The segments are joined into one recording and the transcript starts. The first table sent makes the season's Sourcework project; later tables become sources in it. The original segments are kept."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"When the transcript is ready, the facilitator's after-page shows only that table's lines. They name the voices by first name, mark the lines that mattered with a tag from the season's list, and send the conversation. Naming is optional. The Table page shows the transcript with the names and marks."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A line that was marked keeps the words it had when it was marked, even if the recording is transcribed again."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Contact cards"}]},{"type":"paragraph","content":[{"type":"text","text":"People at a table can scan the card's second QR code and leave a first name, a way to reach them, and three separate choices: may be contacted, may be named, keep anonymous. Naming and anonymous cannot both be chosen. All three start off."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The Table page is the only place a card's contents appear. The facilitator sees how many were left, never what they say."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A person can say you may contact them and leave no way to reach them. The card is kept as they chose it and you are told."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Mark a card as contacted once you have. Approving the use of a name is refused until you have, and for anyone who did not say they could be named."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Deleting a card removes everything on it for good."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Purge"}]},{"type":"paragraph","content":[{"type":"text","text":"Purge lists what is due and lets a coordinator delete it. Nothing is purged on its own."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An unfinished submission, with its answers and audio, is due after 30 days untouched."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A conversation the facilitator never sent is due 30 days after its event ended, with its segments, voices, marks and contact cards. One that holds a card someone has already acted on, by contacting the person or approving their name, is kept, because that card is the record of what they agreed to. The Purge screen says how many are kept."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A conversation the facilitator sent is never purged here. Contact cards and unused raw audio follow the season's report date, which is not set up yet, so neither is due."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An event's organizer will also be able to run the room from the website, seeing where each table is and never what was said. Those website pages are still to come."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If a mailbox is set up on the server, an email goes to it when someone asks to host a session. It says one is waiting and links to Host requests; it carries nothing the person wrote."}]}]}]}]}$body$
);
